// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    bool attacking;
    uint256 got;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function testFuzz_run() public {
        vm.deal(address(c), 1000);
        attacking = true;
        c.getFirstWithdrawalBonus(address(this));
        assertTrue(got <= 100);
    }

    receive() external payable {
        got += msg.value;
        if (attacking) {
            attacking = false;
            try c.getFirstWithdrawalBonus(address(this)) {} catch {}
        }
    }
}
